const decode=value=>new TextDecoder().decode(Uint8Array.from(atob(value),char=>char.charCodeAt(0)));
const files={"/index.html":["","text/html; charset=utf-8"],"/":["","text/html; charset=utf-8"],"/app.js":["","application/javascript; charset=utf-8"],"/finance.js":["","application/javascript; charset=utf-8"],"/research.js":["","application/javascript; charset=utf-8"],"/optimizer-worker.js":["","application/javascript; charset=utf-8"],"/styles.css":["","text/css; charset=utf-8"]};
export function staticAsset(pathname){const file=files[pathname];return file?new Response(decode(file[0]),{headers:{'content-type':file[1],'cache-control':'no-store'}}):null}
